    ],
    "middle-right": [
        [8, 8, 5],
        [5, 5, 5],
        [5, 5, 8]
    ],
    "bottom-left": [
        [9, 4, 4],
        [4, 4, 4],
        [2, 2, 2]
    ]
}

for name, block in blocks.items():
    colors = {}
    for row in block:
        for val in row:
            colors[val] = colors.get(val, 0) + 1
    colors = sorted(colors.items(), key=lambda x: -x[1])
    print(f"{name}: {dict(colors)}")
